import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import Lottie from 'lottie-react';
import menuData from '../data/menuData';
import ProductCard from '../components/ProductCard';
import './Category.css';

const categoryMeta = {
  "Dry Snacks": { icon: '🥨', color: '#FF9933', bgGradient: 'linear-gradient(135deg, #FFF5E6, #FFE8CC)', video: 'https://cdn.coverr.co/videos/coverr-making-sweets-5645/1080p.mp4' },
  "Namkeen": { icon: '🥟', color: '#E67300', bgGradient: 'linear-gradient(135deg, #FFF0E6, #FFE0CC)', video: 'https://cdn.coverr.co/videos/coverr-making-sweets-5645/1080p.mp4' },
  "Sweets": { icon: '🍬', gradient: 'from-amber-500 to-red-600', video: 'https://cdn.coverr.co/videos/coverr-pouring-honey-on-pancakes-2529/1080p.mp4', lottie: 'https://assets2.lottiefiles.com/packages/lf20_ysas4vcp.json', desc: 'Traditional Maharashtrian sweets with longer shelf life' },
  "Wet Sweets": { icon: '🍮', gradient: 'from-amber-700 to-amber-900', video: 'https://cdn.coverr.co/videos/coverr-making-dessert-in-kitchen-5668/1080p.mp4', lottie: 'https://assets1.lottiefiles.com/packages/lf20_hl5imhpf.json', desc: 'Freshly made premium sweets, best enjoyed within days. Advance booking required.' }
};

function Category({ addToCart }) {
  const { category } = useParams();
  const [products, setProducts] = useState([]);
  const [lottieData, setLottieData] = useState(null);
  const [addedMsg, setAddedMsg] = useState('');
  const videoRef = useRef(null);

  const catKey = categories.find(c => c.id === category) ? category : "Dry Snacks";
  const meta = categoryMeta[catKey] || categoryMeta["Dry Snacks"];

  useEffect(() => {
    const filtered = menuData.filter(p => p.category === catKey);
    setProducts(filtered);
  }, [catKey]);

  useEffect(() => {
    if (meta.lottie) {
      fetch(meta.lottie)
        .then(res => res.json())
        .then(data => setLottieData(data))
        .catch(() => {});
    }
  }, [meta.lottie]);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.play().catch(() => {});
    }
  }, [meta.video]);

  const handleAddToCart = (product, weight) => {
    addToCart(product, weight);
    setAddedMsg(`${product.name} (${weight})`);
    setTimeout(() => setAddedMsg(''), 2000);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-orange-50">
      {/* Hero Section */}
      <div className="relative overflow-hidden bg-gradient-to-r from-red-800 via-red-700 to-red-600">
        <div className="absolute inset-0 overflow-hidden">
          <video ref={videoRef} autoPlay muted loop playsInline className="w-full h-full object-cover opacity-25" style={{ filter: 'blur(2px)' }}>
            <source src={meta.video} type="video/mp4" />
          </video>
        </div>
        <div className="relative z-10 container mx-auto px-4 py-16 md:py-24">
          <Link to="/" className="inline-flex items-center text-white/80 hover:text-white text-sm mb-6 transition-colors"><span className="mr-1">←</span> Back to Home</Link>
          <div className="flex flex-col md:flex-row items-center gap-8">
            <div className="flex-shrink-0 w-24 h-24 md:w-32 md:h-32 bg-white/20 backdrop-blur rounded-full flex items-center justify-center animate-float">
              <span className="text-6xl md:text-7xl">{meta.icon}</span>
            </div>
            <div className="text-center md:text-left">
              <h1 className="text-3xl md:text-5xl font-bold text-white mb-4 font-serif">{catKey}</h1>
              <p className="text-white/80 text-lg max-w-2xl leading-relaxed">{meta.desc}</p>
              <div className="flex flex-wrap gap-6 mt-6 justify-center md:justify-start">
                <div className="text-center"><div className="text-2xl font-bold text-yellow-400">{products.length}</div><div className="text-white/70 text-sm">Items</div></div>
                <div className="text-center"><div className="text-2xl font-bold text-yellow-400">₹{Math.min(...products.map(p => Math.min(...Object.values(p.prices))), 0)}</div><div className="text-white/70 text-sm">Starting</div></div>
                <div className="text-center"><div className="text-2xl font-bold text-yellow-400">🚚</div><div className="text-white/70 text-sm">Free Delivery*</div></div>
              </div>
            </div>
          </div>
          {lottieData && (
            <div className="absolute right-4 bottom-4 w-20 h-20 md:w-28 md:h-28 opacity-60">
              <Lottie animationData={lottieData} loop autoplay style={{ width: '100%', height: '100%' }} />
            </div>
          )}
        </div>
      </div>

      {/* Products */}
      <div className="container mx-auto px-4 py-12">
        {catKey === "Wet Sweets" && (
          <div className="mb-8 p-4 bg-gradient-to-r from-yellow-50 to-amber-50 border border-yellow-200 rounded-2xl flex items-center gap-3">
            <span className="text-2xl">⏰</span>
            <div><p className="font-semibold text-amber-800">Advance Booking Required</p><p className="text-sm text-amber-600">Fresh sweets require 1-2 days advance booking for guaranteed freshness</p></div>
          </div>
        )}

        {products.length === 0 ? (
          <div className="text-center py-20">
            <span className="text-6xl block mb-4">📭</span>
            <h3 className="text-2xl font-bold text-gray-700 mb-2">No products in this category</h3>
            <Link to="/" className="inline-block px-6 py-3 bg-red-600 text-white rounded-full font-semibold hover:bg-red-700 transition">Back to Home</Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
            {products.map(product => (
              <ProductCard key={product.id} product={product} onAddToCart={handleAddToCart} />
            ))}
          </div>
        )}

        {/* Delivery Info */}
        <div className="mt-12 bg-gradient-to-r from-red-600 to-red-800 rounded-2xl p-8 text-white">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-center">
            <div><span className="text-3xl block mb-2">🚚</span><h4 className="font-bold text-lg mb-1">Free Delivery</h4><p className="text-white/70 text-sm">On orders above ₹300 within 1km</p></div>
            <div><span className="text-3xl block mb-2">📅</span><h4 className="font-bold text-lg mb-1">Next-Day Delivery</h4><p className="text-white/70 text-sm">For regular items ordered before 6 PM</p></div>
            <div><span className="text-3xl block mb-2">💳</span><h4 className="font-bold text-lg mb-1">Secure Payment</h4><p className="text-white/70 text-sm">COD & UPI payments accepted</p></div>
          </div>
        </div>
      </div>

      {/* Toast */}
      {addedMsg && (
        <div className="fixed bottom-6 right-6 bg-green-500 text-white px-6 py-3 rounded-xl shadow-2xl z-50 animate-slide-up flex items-center gap-2">
          <span>✅</span><span className="font-medium">{addedMsg} added to cart!</span>
        </div>
      )}
    </div>
  );
}

export default Category;
